import java.util.*;
class Solution {
    public int secondLargest(int[] nums) {
        Arrays.sort(nums);
        int largest = nums[nums.length - 1];
        for (int i = nums.length - 2; i >= 0; i--) {
            if (nums[i] != largest) {
                return nums[i];
            }
        }
        return Integer.MIN_VALUE;
    }
}
